$u(t,x)$ is a weak solution to \eqref{PDE1} if 
\begin{align}\label{weak-soln}
\int_{0}^T \int_{\Omega} \bigg( \partial_t \psi(t,x) \cdot u(t,x)  + \nabla_x  \psi(t,x) :  f(u(t,x)) \;  \bigg) d x d t  = 0,
\end{align}
for {all test functions} $\psi \in C^1_c((0,T) \times \Omega; \Bbb{R}^n)$. It satisfies the entropy condition if
\begin{align} \label{weak-entropy}
\int_{0}^T \int_{\Omega} \left( \partial_t \tilde{\psi}(t,x)  u(t,x)   + \nabla_x  \tilde{\psi}(t,x) \cdot q(u(t,x)) \; \right) d x d t  \leq 0,
\end{align}
for {all test functions} $\tilde{\psi} \in C^1_c((0,T) \times \Omega)$, $\tilde{\psi} \geq 0$.

The Young measure $\mathcal{V}_{t,x} \in \mathcal{P}(\mathbb{R}^n)$ with 
\begin{align}\label{initial-ym-0}
\mathcal{V}_{0,x}(\cdot) = \delta(\cdot - u_0(x) ) \mbox{ for  a.a. } x  \in  \Omega
\end{align}
 is a measure-valued solution of \eqref{PDE1}-\eqref{PDE2} if 
\begin{align}\label{PDE-YM}
\int_{0}^T \int_{\Omega} \left( \partial_t \psi(t,x) \cdot \int_{\mathbb{R}^n} \tilde{u} \;  \mathrm{d}\mathcal{V}_{t,x}(\tilde{u})   + \nabla_x  \psi(t,x) : \int_{\mathbb{R}^n} f(\tilde{u}) \; \mathrm{d}\mathcal{V}_{t,x}(\tilde{u}) \right) d x d t  = 0,
\end{align}
for {all test functions} $\psi \in C^1_c((0,T) \times \Omega; \Bbb{R}^n)$;
\begin{align} \label{PDE-YM-entropy}
\int_{0}^T \int_{\Omega} \left( \partial_t \tilde{\psi}(t,x)  \int_{\mathbb{R}^n} \eta(\tilde{u}) \;  \mathrm{d}\mathcal{V}_{t,x}(\tilde{u})   + \nabla_x  \tilde{\psi}(t,x) \cdot \int_{\mathbb{R}^n} q(\tilde{u}) \; \mathrm{d}\mathcal{V}_{t,x}(\tilde{u}) \right) d x d t  \leq 0,
\end{align}
for {all test functions} $\tilde{\psi} \in C^1_c((0,T) \times \Omega)$, $\tilde{\psi} \geq 0.$

\label{def-RPDE}
    The Young measure $\mathcal{V}_{t,x,\omega} \in \mathcal{P}(\mathbb{R}^n)$ is a measure-valued solution of \eqref{RPDE1}-\eqref{RPDE2} with
    \begin{align}\label{Rinitial-ym-0}
\mathcal{V}_{0,x,\omega}(\cdot) = \delta(\cdot - u_0(x,\omega) ) \mbox{ for  a.a. }  x \in \Omega, \ \omega \in D,
\end{align}
if 
\begin{align}\label{RPDE-YM}
\int_{0}^T \int_{\Omega} \int_D \left( \partial_t \psi(t,x)  \int_{\mathbb{R}^n} \tilde{u} \;  \mathrm{d}\mathcal{V}_{t,x,\omega}(\tilde{u})   + \nabla_x  \psi(t,x) : \int_{\mathbb{R}^n} f(\tilde{u}) \; \mathrm{d}\mathcal{V}_{t,x,\omega}(\tilde{u}) \right) \phi(\omega) p(\omega)  d \omega d x d t  = 0,
\end{align}
for all test functions $\psi \in C^1_c((0,T) \times \Omega; \Bbb R^n),$ $\phi \in C(D) $; and 
\begin{align} \label{RPDE-YM-entropy}
\int_{0}^T \int_{\Omega} \int_D \left( \partial_t \tilde{\psi}(t,x)  \int_{\mathbb{R}^n} \eta(\tilde{u}) \;  \mathrm{d}\mathcal{V}_{t,x,\omega}(\tilde{u})   + \nabla_x  \tilde{\psi}(t,x) \cdot \int_{\mathbb{R}^n} q(\tilde{u}) \; \mathrm{d}\mathcal{V}_{t,x,\omega}(\tilde{u})  \right)\tilde{\phi}(\omega) p(\omega) d \omega d x d t  \leq 0,
\end{align}
for all test functions $\tilde{\psi} \in C^1_c((0,T) \times \Omega),$ $\tilde{\phi} \in C(D) $, $\tilde{\psi} \geq 0, \tilde{\phi} \geq 0$.

\label{example:1D-rarefaction}\rm
	The computational domain is $[-3,3]$, and the outflow boundary condition is applied. 
	The initial data is 
	\begin{equation*}
		u_0(x) = \begin{cases}
		-1,& \mbox{if}~ x < 0,\\
		2,& \mbox{if}~ x > 0.
		\end{cases}
	\end{equation*} 
In the experiment we take $T=1$ and $[\xi_{\min}, \xi_{\max}] = [-1.05, 2.05]$.  

Figure~\ref{ex1-fig-Burgers} shows the measure characterized by $F(T,x,\xi)$, i.e.\ $\int_{K_{\xi}^l} F(T,x,\xi) d \xi $ or $F_{kl}^{N_t}$, solution $u(T,x)$, energy $\hat{E}(T,x)$, the evolution of total energy $ \int_{\Omega}\hat{E} dx$ and the total energy defects $\int_{\Omega}\mathfrak{E} dx $ obtained with the discretization parameters $(N_t,N_x,N_{\xi}) = (150,200,200)$.  Further, the $L^p$-errors and corresponding rates on  consecutively refined meshes are presented in Table~\ref{table1}.

\label{example:1D-shock}\rm
	The computational domain is $[-3,3]$. 
	The initial data is 
	\begin{equation*}
		u_0(x) = \begin{cases}
		2,& \mbox{if}~ x < 0,\\
		-1,& \mbox{if}~ x > 0.
		\end{cases}
	\end{equation*} 
In the experiment we take $T=1$ and $[\xi_{\min}, \xi_{\max}] = [-1.05, 2.05]$.  

Figure~\ref{ex2-fig-Burgers} shows the measure characterized by $F(T,x,\xi)$, solution $u(T,x)$, energy $\hat{E}(T,x)$, the evolution of total energy $ \int_{\Omega}\hat{E} dx$ and the total energy defects $\int_{\Omega}\mathfrak{E} dx $ obtained with $(N_t,N_x,N_{\xi}) = (150,200,200)$.  Further, the $L^p$-errors and corresponding rates on consecutively refined meshes are presented in Table~\ref{table2}.

\rm

The computational domain is chosen to be $\Omega = [0,1]$ and the periodic boundary conditions are applied. The initial conditions read
\begin{align}
\left(\varrho_0, \, m_0 \right)(x) = \begin{cases}
(1,\, 1-\epsilon^2/2) & \mbox{ if } x \in [0, 0.2] \cup [0.8,1], \\
(1+\epsilon^2,\, 1)	& \mbox{ if } x \in (0.2, 0.3], \\
(1,\, 1+\epsilon^2/2)	& \mbox{ if } x \in (0.3, 0.7], \\
(1-\epsilon^2,\, 1)	& \mbox{ if } x \in (0.7, 0.8].
\end{cases}
\end{align}
In this experiment, we take  $\epsilon = 0.8$, $T=0.06$ and $(\varrho, m)\in [0.105, 1.805]\times[0.205,1.805]$.  

Figure~\ref{ex1-fig-BEuler} presents the density $\varrho$, momentum $m$, the evolution of total energy $\int_{\Omega} \hat{E} dx$ and energy defect $\int_{\Omega} \mathfrak{E} dx$ obtained with  $(N_t,N_x,N_{\varrho},N_{m}) = (200,300,151,151)$.

\label{EX:AC-2}\rm 
The computational domain is set to  $\Omega = [-1,1]$ and the initial data are chosen as follows
\begin{align}
u_0(x) = \begin{cases}
1, & \mbox{ if } |x| < 0.5, \\
-1, & \mbox{ else.}  
\end{cases}
\end{align}
In this experiment we take $T = 0.02$ and $[\xi_{\min}, \xi_{\max}] =  [-1.05, 1.05]$.  

\medskip 
Figure~\ref{ex3-fig-AC} presents the measure characterized by $F(T,x,\xi)$, solution $u(T,x)$, 
the evolution of total energy $ \int_{\Omega}\hat{E} dx$,  the defect of total energy $\int_{\Omega}\mathfrak{E} dx$, as well as the defect of total regularized energy $\int_{\Omega}\mathfrak{E}^{RE} dx$ obtained with $(N_t,N_x,N_{U}) = (150,80,100)$.
